const MOD = 998244353;
const MaxN = 2e3 + 23;

function mulmod(a, b) {
    const ah = Math.floor(a / 65536), al = a % 65536;
    return ((ah * b % MOD) * 65536 + al * b) % MOD;
}

function bpow(a, b) {
    if (!b)
        return 1;
    let res = bpow(a, b >> 1);
    res = mulmod(res, res);
    if (b & 1)
        res = mulmod(res, a);
    return res;
}

let pless = 0, pgreater = 0;
const CP = new Array(MaxN);
for (let i = 0; i < MaxN; ++i)
    CP[i] = new Int32Array(MaxN);
const STRONG = new Int32Array(MaxN);
const ans = new Int32Array(MaxN);

function calcCP(n, s) {
    if (!s)
        CP[n][s] = 1;
    else {
        CP[n][s] = mulmod(CP[n - 1][s - 1], bpow(pgreater, n - s)) + mulmod(CP[n - 1][s], bpow(pless, s));
        if (CP[n][s] >= MOD)
            CP[n][s] -= MOD;
    }
}

function calcStrong(n) {
    STRONG[n] = 1;
    if (n > 1) {
        for (let i = 1; i < n; ++i) {
            STRONG[n] -= mulmod(STRONG[i], CP[n][i]);
            if (STRONG[n] < 0)
                STRONG[n] += MOD;
        }
    }
}

function calcAns(n) {
    if (n < 2)
        ans[n] = 0;
    else {
        for (let i = 1; i <= n; ++i) {
            const val = (i * (n - i) + Math.floor((i * (i - 1)) / 2) + (i < n ? ans[i] : 0) + ans[n - i]) % MOD;
            ans[n] += mulmod(mulmod(STRONG[i], CP[n][i]), val);
            if (ans[n] >= MOD)
                ans[n] -= MOD;
        }
        let coef = 1 - mulmod(STRONG[n], CP[n][n]);

        if (coef < 0)
            coef += MOD;

        ans[n] = mulmod(ans[n], bpow(coef, MOD - 2));
    }
}

function main() {
    const data = require('fs').readFileSync(0, 'utf8').split(/\s+/);
    let ptr = 0;
    const n = parseInt(data[ptr++]);
    const a = parseInt(data[ptr++]);
    const b = parseInt(data[ptr++]);

    pless = mulmod(a, bpow(b, MOD - 2));
    pgreater = mulmod(b - a, bpow(b, MOD - 2));

    for (let i = 0; i <= n; ++i)
        for (let j = 0; j <= i; ++j)
